# NickFlix 4.7 avatar generator: original flat-design SVG art -> 240px PNGs (rendered with headless Chrome).
# Avatars 0-15 (mkav.py) are untouched; new ones are numbered from 16.
import json, os, sys, colorsys
OUT_SVG = 'dist/avsrc'; APP = sys.argv[1] if len(sys.argv) > 1 else 'app'
W = '#ffffff'; K = '#1b1b24'
def hx(h, s, l):
    r, g, b = colorsys.hls_to_rgb(h / 360, l, s); return '#%02x%02x%02x' % (int(r * 255), int(g * 255), int(b * 255))
def pal(h): return hx(h, .78, .55), hx((h + 25) % 360, .7, .28)
def svg(c1, c2, body, n):
    return ('<svg xmlns="http://www.w3.org/2000/svg" width="240" height="240" viewBox="0 0 240 240">'
            '<defs><linearGradient id="g%d" x1="0" y1="0" x2="0.3" y2="1"><stop offset="0" stop-color="%s"/><stop offset="1" stop-color="%s"/></linearGradient>'
            '<clipPath id="c%d"><rect width="240" height="240" rx="36"/></clipPath></defs>'
            '<g clip-path="url(#c%d)"><rect width="240" height="240" fill="url(#g%d)"/>'
            '<circle cx="205" cy="20" r="80" fill="#fff" opacity=".08"/><circle cx="10" cy="235" r="60" fill="#000" opacity=".10"/>%s</g></svg>') % (n, c1, c2, n, n, n, body)

# ---------------- smileys (16 colours x expression) ----------------
def eyes(kind):
    if kind == 'dot': return '<circle cx="88" cy="100" r="13" fill="#fff"/><circle cx="152" cy="100" r="13" fill="#fff"/>'
    if kind == 'wink': return '<circle cx="88" cy="100" r="13" fill="#fff"/><path d="M138 102 q14 -14 28 0" stroke="#fff" stroke-width="9" fill="none" stroke-linecap="round"/>'
    if kind == 'happy': return '<path d="M74 104 q14 -18 28 0 M138 104 q14 -18 28 0" stroke="#fff" stroke-width="9" fill="none" stroke-linecap="round"/>'
    if kind == 'shades': return '<path d="M58 84 h124 v8 h-6 q-2 30 -28 30 q-24 0 -26 -26 h-4 q-2 26 -26 26 q-26 0 -28 -30 h-6z" fill="#14141c"/><path d="M76 92 l14 0 l-12 14z" fill="#fff" opacity=".35"/>'
    if kind == 'heart': return ''.join('<path transform="translate(%d 86)" d="M0 8 c0 -10 14 -12 16 -2 c2 -10 16 -8 16 2 c0 10 -16 20 -16 20 c0 0 -16 -10 -16 -20z" fill="#ff3b6b" stroke="#fff" stroke-width="3"/>' % x for x in (72, 136))
    if kind == 'star': return ''.join('<path transform="translate(%d 100)" d="M0 -18 L5 -6 L18 -6 L8 2 L12 15 L0 7 L-12 15 L-8 2 L-18 -6 L-5 -6z" fill="#ffe14d" stroke="#fff" stroke-width="2"/>' % x for x in (88, 152))
    if kind == 'sleepy': return '<path d="M74 100 q14 12 28 0 M138 100 q14 12 28 0" stroke="#fff" stroke-width="8" fill="none" stroke-linecap="round"/><text x="176" y="70" font-family="Arial" font-weight="900" font-size="34" fill="#fff">z</text><text x="196" y="48" font-family="Arial" font-weight="900" font-size="24" fill="#fff">z</text>'
    if kind == 'big': return '<circle cx="88" cy="98" r="20" fill="#fff"/><circle cx="152" cy="98" r="20" fill="#fff"/><circle cx="93" cy="102" r="9" fill="%s"/><circle cx="157" cy="102" r="9" fill="%s"/>' % (K, K)
def mouth(kind):
    return {'smile': '<path d="M78 140 q42 46 84 0" stroke="#fff" stroke-width="10" fill="none" stroke-linecap="round"/>',
            'grin': '<path d="M70 134 h100 q-8 56 -50 56 q-42 0 -50 -56z" fill="#fff"/><path d="M92 170 q28 22 56 0 q-28 10 -56 0z" fill="#ff7a8a"/>',
            'tongue': '<path d="M78 138 q42 40 84 0" stroke="#fff" stroke-width="10" fill="none" stroke-linecap="round"/><path d="M118 156 h28 v14 q-14 18 -28 0z" fill="#ff6b81"/>',
            'o': '<ellipse cx="120" cy="160" rx="18" ry="22" fill="#fff"/>',
            'smirk': '<path d="M88 152 q40 18 70 -12" stroke="#fff" stroke-width="10" fill="none" stroke-linecap="round"/>',
            'flat': '<path d="M90 156 h60" stroke="#fff" stroke-width="10" stroke-linecap="round"/>',
            'laugh': '<path d="M74 136 h92 q-6 50 -46 50 q-40 0 -46 -50z" fill="#fff"/>'}[kind]
SMILEY = [('dot', 'smile', 0), ('happy', 'grin', 30), ('wink', 'tongue', 50), ('shades', 'smirk', 140), ('heart', 'smile', 330), ('star', 'laugh', 270),
          ('big', 'o', 190), ('sleepy', 'flat', 220), ('dot', 'laugh', 100), ('happy', 'smile', 300), ('wink', 'smirk', 10), ('shades', 'grin', 205),
          ('big', 'smile', 80), ('heart', 'laugh', 355), ('star', 'tongue', 170), ('happy', 'tongue', 250)]

# ---------------- illustrations ----------------
def text(t, size=120, y=160, col='#fff', fam='Arial Black, Arial', w=900):
    return '<text x="120" y="%d" text-anchor="middle" font-family="%s" font-weight="%d" font-size="%d" fill="%s">%s</text>' % (y, fam, w, size, col, t)
